package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
import com.tom_roush.pdfbox.android.PDFBoxResourceLoader;import com.tom_roush.pdfbox.pdmodel.*;import com.tom_roush.pdfbox.pdmodel.font.PDType1Font;
@androidx.media3.common.util.UnstableApi
public class MemoryFlowTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private final List<File> files=new ArrayList<>();private Activity anchor,opened;private MemoryActivity screen;private MemoryAudio.Factory factory;private CountDownLatch gate;
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{for(int i=0;i<400;i++){boolean[] ready={false};ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception error){throw new RuntimeException(error);}});if(ready[0])return;Thread.sleep(50);}fail("Memory scenario timed out: "+MemoryIndexService.message);}
 private File file(String suffix)throws IOException{File f=File.createTempFile("memory-test-",suffix,c.getCacheDir());files.add(f);return f;}
 private File asset(String name)throws IOException{File f=file(".mp4");try(InputStream in=ins.getContext().getAssets().open(name);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return f;}
 private final MemoryIndexer.Control control=new MemoryIndexer.Control(){public void check()throws IOException{if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();}public void progress(String text,long at,long total){}};
 @Before public void before()throws Exception{factory=MemoryAudio.factory;c.deleteDatabase("multimedia-memory.db");anchor=ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->anchor.hasWindowFocus());}
 @After public void after()throws Exception{MemoryIndexService.cancel();if(gate!=null)gate.countDown();waitFor(()->!MemoryIndexService.running);MemoryAudio.factory=factory;try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(ins.getUiAutomation().executeShellCommand("input keyevent 224"))){while(in.read()!=-1){}}try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(ins.getUiAutomation().executeShellCommand("wm dismiss-keyguard"))){while(in.read()!=-1){}}ins.runOnMainSync(()->{if(opened!=null)opened.finish();if(screen!=null)screen.finish();if(anchor!=null)anchor.finish();});ins.waitForIdleSync();for(File f:files)f.delete();}
 private MemoryStore.Source subtitles(File owner)throws Exception{File s=file(".srt");try(OutputStream out=new FileOutputStream(s)){out.write("1\n00:00:00,100 --> 00:00:00,900\nSegurança no trânsito\n\n2\n00:00:01,000 --> 00:00:02,500\nExplicação sobre juros compostos\n".getBytes(StandardCharsets.UTF_8));}MemoryStore.Source source=MemoryStore.source(c,Uri.fromFile(owner),Uri.fromFile(s),"Aula de teste","subtitle");assertEquals(2,MemoryIndexer.index(c,source,control));return source;}
 private File pdf()throws Exception{PDFBoxResourceLoader.init(c);File f=file(".pdf");try(PDDocument doc=new PDDocument()){for(String text:new String[]{"Primeira pagina sobre seguranca","Segunda pagina sobre juros compostos"}){PDPage page=new PDPage();doc.addPage(page);try(PDPageContentStream out=new PDPageContentStream(doc,page)){out.beginText();out.setFont(PDType1Font.HELVETICA,14);out.newLineAtOffset(40,700);out.showText(text);out.endText();}}doc.save(f);}return f;}
 @Test public void pdfFindsAccentIndependentTextAndOpensCorrectPage()throws Exception{File pdf=pdf();MemoryStore.Source source=MemoryStore.source(c,Uri.fromFile(pdf),null,"Apostila","pdf");assertEquals(2,MemoryIndexer.index(c,source,control));MemoryStore.Hit hit;try(MemoryStore store=new MemoryStore(c)){List<MemoryStore.Hit> found=store.search("ache a explicação sobre juros",false);assertEquals(0,found.size());found=store.search("onde fala sobre juros",false);assertEquals(1,found.size());hit=found.get(0);assertEquals(1,hit.page);}openScreen();Instrumentation.ActivityMonitor monitor=ins.addMonitor(PdfActivity.class.getName(),null,false);try{invokeOpen(hit);opened=ins.waitForMonitorWithTimeout(monitor,15000);assertNotNull(opened);assertEquals(1,opened.getIntent().getIntExtra("onda_page",-1));waitFor(()->{java.lang.reflect.Field p=PdfActivity.class.getDeclaredField("page");p.setAccessible(true);return p.getInt(opened)==1;});}finally{ins.removeMonitor(monitor);}}
 @Test public void subtitlesArePersistentSearchableAndFavoriteRemovalKeepsOriginal()throws Exception{File owner=asset("combined.mp4");MemoryStore.Source source=subtitles(owner);long size=owner.length();try(MemoryStore store=new MemoryStore(c)){List<MemoryStore.Hit> found=store.search("JUROS comp",false);assertEquals(1,found.size());MemoryStore.Hit hit=found.get(0);assertEquals(1000,hit.start);assertEquals(2500,hit.end);store.favorite(hit);}try(MemoryStore store=new MemoryStore(c)){assertEquals(1,store.search("",true).size());assertEquals(2,MemoryIndexer.index(c,source,control));assertEquals(1,store.search("",true).size());store.remove(source.id);assertTrue(store.search("juros",false).isEmpty());assertTrue(store.search("",true).isEmpty());}assertEquals(size,owner.length());}
 @Test public void cancelledReplacementRollsBackOldResultsAndMarks()throws Exception{File owner=asset("combined.mp4");MemoryStore.Source source=subtitles(owner);try(MemoryStore store=new MemoryStore(c)){store.favorite(store.search("juros",false).get(0));try{store.replace(source,w->{w.add(new MemoryText.Cue(1,2,-1,"Texto incompleto"));throw new InterruptedIOException("cancelado");});fail();}catch(InterruptedIOException expected){}assertEquals(1,store.search("juros",false).size());assertTrue(store.search("incompleto",false).isEmpty());assertEquals(1,store.search("",true).size());}}
 @Test public void mediaDecoderFeedsAllSpeechWindowsWithBoundedAccurateOffsets()throws Exception{File wav=AudioTestFixtures.tone(c,30000);files.add(wav);List<Integer> lengths=new ArrayList<>();MemoryAudio.factory=context->new MemoryAudio.Recognizer(){public String recognize(float[] pcm){lengths.add(pcm.length);return "Trocar o pneu com segurança";}public void cancel(){}public void close(){}};MemoryStore.Source source=MemoryStore.source(c,Uri.fromFile(wav),null,"Manual falado","audio");assertEquals(4,MemoryIndexer.index(c,source,control));assertEquals(4,lengths.size());for(int i=0;i<3;i++)assertEquals(128000,(int)lengths.get(i));assertEquals(96000,(int)lengths.get(3),2);try(MemoryStore store=new MemoryStore(c)){List<MemoryStore.Hit> hits=store.search("trocar pneu",false);assertEquals(4,hits.size());assertEquals(0,hits.get(0).start,2);assertEquals(8000,hits.get(1).start,2);assertEquals(24000,hits.get(3).start,2);assertEquals(30000,hits.get(3).end,2);}}
 @Test public void foregroundIndexSurvivesScreenOffAndActivityRecreation()throws Exception{File wav=AudioTestFixtures.tone(c,30000);files.add(wav);CountDownLatch entered=new CountDownLatch(1);gate=new CountDownLatch(1);MemoryAudio.factory=context->new MemoryAudio.Recognizer(){public String recognize(float[] pcm)throws IOException{entered.countDown();try{gate.await(15,TimeUnit.SECONDS);}catch(InterruptedException e){throw new InterruptedIOException();}return "Explicação local sobre tecnologia";}public void cancel(){gate.countDown();}public void close(){}};MemoryStore.Source source=MemoryStore.source(c,Uri.fromFile(wav),null,"Aula em segundo plano","audio");try(MemoryStore old=new MemoryStore(c)){old.replace(source,w->w.add(new MemoryText.Cue(0,1000,-1,"Índice anterior disponível")));}openScreen();ins.runOnMainSync(()->assertTrue(MemoryIndexService.start(c,source,false)));assertTrue(entered.await(15,TimeUnit.SECONDS));ExecutorService reader=Executors.newSingleThreadExecutor();try{assertEquals(1,(int)reader.submit(()->{try(MemoryStore old=new MemoryStore(c)){return old.search("anterior",false).size();}}).get(5,TimeUnit.SECONDS));}finally{reader.shutdownNow();}ins.runOnMainSync(()->screen.finish());try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(ins.getUiAutomation().executeShellCommand("input keyevent 223"))){while(in.read()!=-1){}}gate.countDown();waitFor(()->!MemoryIndexService.running);try(MemoryStore store=new MemoryStore(c)){assertEquals(4,store.search("tecnologia",false).size());}assertTrue(MemoryIndexService.message.contains("indexados"));}
 @Test public void cancellationAbortsRecognizerAndPreservesOldIndex()throws Exception{File wav=AudioTestFixtures.tone(c,30000);files.add(wav);MemoryStore.Source source=MemoryStore.source(c,Uri.fromFile(wav),null,"Arquivo","audio");try(MemoryStore store=new MemoryStore(c)){store.replace(source,w->w.add(new MemoryText.Cue(0,1000,-1,"Resultado anterior preservado")));}CountDownLatch entered=new CountDownLatch(1);gate=new CountDownLatch(1);MemoryAudio.factory=context->new MemoryAudio.Recognizer(){public String recognize(float[] pcm)throws IOException{entered.countDown();try{gate.await(15,TimeUnit.SECONDS);}catch(InterruptedException e){throw new InterruptedIOException();}return "Resultado novo parcial";}public void cancel(){gate.countDown();}public void close(){}};ins.runOnMainSync(()->MemoryIndexService.start(c,source,false));assertTrue(entered.await(15,TimeUnit.SECONDS));ins.runOnMainSync(MemoryIndexService::cancel);waitFor(()->!MemoryIndexService.running);try(MemoryStore store=new MemoryStore(c)){assertEquals(1,store.search("anterior",false).size());assertTrue(store.search("parcial",false).isEmpty());}}
 @Test public void indexedRangeExportsRealMp3WithoutChapterMarkers()throws Exception{File owner=asset("combined.mp4");subtitles(owner);MemoryStore.Hit hit;try(MemoryStore store=new MemoryStore(c)){hit=store.search("juros",false).get(0);}Uri root=DocumentsContract.buildTreeDocumentUri("br.com.onda.player.test.batchdocs","root"),folder=DocumentsContract.buildDocumentUriUsingTree(root,"root");Uri target=DocumentsContract.createDocument(c.getContentResolver(),folder,"audio/mpeg","memory-test-"+System.nanoTime()+".mp3");assertNotNull(target);try{ChapterExportJob job=new ChapterExportJob(UUID.randomUUID().toString(),Uri.fromFile(owner),target,hit.source.stamp,"Trecho",hit.start,hit.end,3000,256,hit.tag);assertEquals(hit.tag,ChapterExportJob.parse(job.json().toString()).memoryTag);ChapterExportTask.run(c,job,c.getContentResolver().openAssetFileDescriptor(target,"rw"),new ChapterExportTask.Control(){public void check(){}public void progress(long at,long total){}public void stage(String text){}});File mp3=file(".mp3");try(InputStream in=c.getContentResolver().openInputStream(target);OutputStream out=new FileOutputStream(mp3)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}assertTrue(new ChapterExportTest().decodedRms(mp3,1500)>100);}finally{DocumentsContract.deleteDocument(c.getContentResolver(),target);}}
 @Test public void memoryScreenSearchesSavedResultsAndVoiceNavigationFindsIt()throws Exception{File owner=asset("combined.mp4");subtitles(owner);assertEquals(VoiceCommand.Action.OPEN_MEMORY,VoiceCommand.parse("abra memória multimídia").action);openScreen();ins.runOnMainSync(()->{try{java.lang.reflect.Field f=MemoryActivity.class.getDeclaredField("query");f.setAccessible(true);((EditText)f.get(screen)).setText("juros");java.lang.reflect.Method m=MemoryActivity.class.getDeclaredMethod("search");m.setAccessible(true);m.invoke(screen);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->{java.lang.reflect.Field f=MemoryActivity.class.getDeclaredField("hits");f.setAccessible(true);return ((List<?>)f.get(screen)).size()==1;});ins.waitForIdleSync();Thread.sleep(250);android.graphics.Bitmap shot=ins.getUiAutomation().takeScreenshot();assertNotNull(shot);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"memory-results.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}}
 @Test public void absentSpeechModelFailsWithoutDownloadingOrDamagingTextIndex()throws Exception{File wav=AudioTestFixtures.tone(c,1000);files.add(wav);MemoryStore.Source source=MemoryStore.source(c,Uri.fromFile(wav),null,"Sem modelo","audio");try(MemoryStore store=new MemoryStore(c)){store.replace(source,w->w.add(new MemoryText.Cue(0,1000,-1,"Conteúdo original válido")));}assertFalse(LiveSpeechModels.installed(c,LiveSpeechModels.Model.BASE));try{MemoryIndexer.index(c,source,control);fail("A missing optional model must not download implicitly");}catch(IOException expected){assertTrue(expected.getMessage().contains("modelo"));}try(MemoryStore store=new MemoryStore(c)){assertEquals(1,store.search("original",false).size());}}
 @Test public void forgedMemoryTagCannotAuthorizeArbitraryRangeExport()throws Exception{File owner=asset("combined.mp4");subtitles(owner);long length=owner.length();Uri root=DocumentsContract.buildTreeDocumentUri("br.com.onda.player.test.batchdocs","root"),folder=DocumentsContract.buildDocumentUriUsingTree(root,"root"),target=DocumentsContract.createDocument(c.getContentResolver(),folder,"audio/mpeg","memory-rejected-"+System.nanoTime()+".mp3");assertNotNull(target);try{ChapterExportJob job=new ChapterExportJob(UUID.randomUUID().toString(),Uri.fromFile(owner),target,AudioChapterStore.stamp(c,Uri.fromFile(owner)),"Inválido",100,800,3000,192,String.join("",Collections.nCopies(64,"0")));try{ChapterExportTask.run(c,job,c.getContentResolver().openAssetFileDescriptor(target,"rw"),new ChapterExportTask.Control(){public void check(){}public void progress(long at,long total){}public void stage(String text){}});fail("Unknown tags must be refused");}catch(IOException expected){}assertEquals(length,owner.length());}finally{try{DocumentsContract.deleteDocument(c.getContentResolver(),target);}catch(Exception ignored){}}}
 private void openScreen()throws Exception{screen=(MemoryActivity)ins.startActivitySync(new Intent(c,MemoryActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->screen.hasWindowFocus());}
 private void invokeOpen(MemoryStore.Hit hit){ins.runOnMainSync(()->{try{java.lang.reflect.Method m=MemoryActivity.class.getDeclaredMethod("open",MemoryStore.Hit.class);m.setAccessible(true);m.invoke(screen,hit);}catch(Exception e){throw new RuntimeException(e);}});}
}
